var app = new Elysia().use(openapi({
  documentation: {
    info: {
      title: "wdawrs27 API Documentation",
      version: "0.0.0"
    }
  }
})).onBeforeHandle(async ({ request, set }) => {
  try {
    const clientIp = request.headers.get("x-forwarded-for") ?? "local";
    const windowKey = Math.floor(Date.now() / 60000);
    const redisKey = `ratelimit:${clientIp}:${windowKey}`;
    const requests = await redis.incr(redisKey);
    if (requests === 1) {
      await redis.expire(redisKey, 60);
    } else if (requests > 10) {
      set.status = 429;
      return { error: "Too many requests, please try again later." };
    }
  } catch (err) {
    console.error("Redis rate-limiter failed, failing open:", err);
  }
}).get("/", () => ({
  name: "Game Backend API",
  status: "online",
  version: appVersion,
  timestamp: new Date().toISOString()
}), {
  detail: {
    summary: "Home Route",
    description: "General API information"
  }
}).use(gameRoutes);
if (import.meta.main) {
  app.listen(3000);
  console.log(`\uD83E\uDD8A Elysia is running at ${app.server?.hostname}:${app.server?.port}`);
}
var src_default = app;
export {
  src_default as default
};
